commits.content:
/* app global css */
@import './responsive.css';

/* Base responsive design - Mobile first approach */
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
  line-height: 1.5;
}

/* Container constraints - Max width 900px (tablet size) */
.container {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 16px;
}

/* Responsive utilities */
.desktop-only {
  display: none;
}

.mobile-only {
  display: block;
}

.tablet-up {
  display: none;
}

/* Mobile first breakpoints - Max 900px */
@media (max-width: 480px) {
  .container {
    padding: 0 12px;
  }

  .mobile-xs-only {
    display: block !important;
  }

  .mobile-xs-hide {
    display: none !important;
  }
}

@media (min-width: 481px) and (max-width: 900px) {
  .tablet-up {
    display: block !important;
  }

  .mobile-xs-only {
    display: none !important;
  }
}

@media (min-width: 769px) and (max-width: 900px) {
  .desktop-only {
    display: block !important;
  }

  .mobile-only {
    display: none !important;
  }
}

/* Responsive grid system */
.row {
  display: flex;
  flex-wrap: wrap;
  margin: 0 -8px;
}

.col {
  flex: 1;
  padding: 0 8px;
}

.col-12 { width: 100%; }
.col-6 { width: 50%; }
.col-4 { width: 33.333%; }
.col-3 { width: 25%; }

@media (max-width: 480px) {
  .col-6, .col-4, .col-3 {
    width: 100%;
  }
}

/* Responsive text sizes */
.text-responsive {
  font-size: 14px;
}

@media (min-width: 481px) {
  .text-responsive {
    font-size: 16px;
  }
}

@media (min-width: 769px) {
  .text-responsive {
    font-size: 18px;
  }
}

/* Common responsive utilities */
.w-full { width: 100%; }
.h-full { height: 100%; }
.min-h-screen { min-height: 100vh; }

.p-0 { padding: 0; }
.p-1 { padding: 8px; }
.p-2 { padding: 16px; }
.p-3 { padding: 24px; }
.p-4 { padding: 32px; }

.m-0 { margin: 0; }
.m-1 { margin: 8px; }
.m-2 { margin: 16px; }
.m-3 { margin: 24px; }
.m-4 { margin: 32px; }

/* Responsive spacing adjustments */
@media (max-width: 480px) {
  .p-4 { padding: 16px; }
  .p-3 { padding: 16px; }
  .m-4 { margin: 16px; }
  .m-3 { margin: 16px; }
}
